actions.script:
String apiKey = ec.service.sync()
    .name('growerp.100.WebsiteTranslationServices100.get#TranslationApiKey')
    .parameters([ownerPartyId: ownerPartyId]).call()?.apiKey
try {
    def out = ec.service.sync()
        .name('growerp.100.GlAccountTranslationServices100.translate#GlAccountNames')
        .parameters([targetLocale: targetLocale, sourceLocale: sourceLocale,
                     apiKey: apiKey, ownerPartyId: ownerPartyId])
        .call()
    if (ec.message.hasError()) throw new Exception(ec.message.getErrorsString())
    ec.logger.info("process#GlAccountTranslation stored ${out?.translatedCount} names for ${targetLocale}")
    if (notifyUserId) {
        ec.makeNotificationMessage().topic('glAccountTranslation')
            .userId(notifyUserId as String).title('GL account names translated')
            .message([targetLocale: targetLocale, status: 'COMPLETED',
                      translatedCount: out?.translatedCount,
                      message: "GL account names translated into ${targetLocale}"])
            .send()
    }
} catch (Throwable t) {
    ec.logger.error("process#GlAccountTranslation failed: ${t.message}", t)
    ec.message.clearErrors()
    if (notifyUserId) {
        ec.makeNotificationMessage().topic('glAccountTranslation')
            .userId(notifyUserId as String).title('GL account translation failed')
            .message([targetLocale: targetLocale, status: 'FAILED',
                      message: (t.message ?: 'unknown error').take(4000)])
            .send()
    }
}

// the enum descriptions are localized fields: read them in the language they are
// stored in, or a second run would key the rows on its own translation
List enumTexts = classAndTypeEnums
    .collect { (it.getNoCheckSimple('description') ?: '').toString().trim() }
    .findAll { it }
List accountNames = ec.entity.find('mantle.ledger.account.GlAccount')
    .selectField('accountName').disableAuthz().list()
    .collect { (it.accountName ?: '').toString().trim() }.findAll { it }
context.ledgerTexts = (accountNames + enumTexts).unique()
